'use strict';
(async function(){
  if(!window.AFApi||!window.AF_RUNTIME)return;
  const API=window.AFApi,cfg=window.AF_RUNTIME;
  const P={online:false,health:null,installations:[],repositories:[],backendProjects:new Map(),runPollers:new Map(),lastError:null};
  window.AF_PROD=P;
  const array=v=>Array.isArray(v)?v:Array.isArray(v?.items)?v.items:Array.isArray(v?.projects)?v.projects:Array.isArray(v?.repositories)?v.repositories:Array.isArray(v?.runs)?v.runs:[];
  const value=(o,...keys)=>{for(const k of keys)if(o&&o[k]!==undefined&&o[k]!==null)return o[k]};
  const statusMap=s=>({completed:'success',succeeded:'success',failure:'failed',error:'failed',pending:'queued',created:'queued',canceled:'cancelled'}[String(s||'').toLowerCase()]||String(s||'queued').toLowerCase());
  function announce(msg,kind='success'){try{toast(msg)}catch{console[kind==='error'?'error':'log'](msg)}}
  function setMode(online){P.online=online;document.documentElement.dataset.afRuntime=online?'production':'demo';}
  async function probe(){if(cfg.mode==='demo'){setMode(false);return false}try{P.health=await API.health();setMode(P.health?.status==='ready');return P.online}catch(e){P.lastError=e;setMode(false);return false}}
  function normalizeRepo(raw,installationId){const full=value(raw,'full_name','fullName','name')||'repository';const name=String(full).split('/').pop();const owner=value(raw,'owner')?.login||String(full).split('/')[0]||'github';const branch=value(raw,'default_branch','defaultBranch')||'main';return {id:'gh_'+String(value(raw,'id','repository_id')||full).replace(/[^a-z0-9_-]/gi,'_'),backendRepoId:value(raw,'id','repository_id'),installationId,fullName:full,name,owner,description:value(raw,'description')||'Authorized GitHub repository',language:value(raw,'language')||'Repository',framework:'Detected during analysis',files:Number(value(raw,'size','files')||0),branches:[branch],branch,sha:value(raw,'sha','commit_sha')||'resolve-on-analysis',confidence:0,type:'web',color:'#6387ff',workflow:1,status:'ready',validated:false,customCommands:{},real:true};}
  function normalizeProject(raw){const id=String(value(raw,'id','project_id','uuid'));const full=value(raw,'repository_full_name','repo_full_name','repository','name')||id;return {id,backendProjectId:id,name:value(raw,'name')||String(full).split('/').pop(),owner:String(full).split('/')[0]||'github',description:value(raw,'description')||'Connected repository',language:value(raw,'language')||'Detected',framework:value(raw,'framework')||'Repository',files:Number(value(raw,'files','file_count')||0),branches:[value(raw,'branch','default_branch')||'main'],branch:value(raw,'branch','default_branch')||'main',sha:value(raw,'commit_sha','sha')||'pending',confidence:Number(value(raw,'confidence')||0),type:'web',color:'#6387ff',workflow:Number(value(raw,'workflow_version','workflow')||1),status:value(raw,'status')||'ready',validated:Boolean(value(raw,'validated')),customCommands:{},real:true,raw};}
  function normalizeRun(raw,projectId){const id=String(value(raw,'id','run_id'));return {id,backendRunId:id,project:String(value(raw,'project_id')||projectId),sha:value(raw,'commit_sha','sha')||'pending',branch:value(raw,'branch')||'main',workflow:Number(value(raw,'workflow_version','workflow')||1),status:statusMap(value(raw,'status')),mode:'production',parent:value(raw,'parent_run_id'),trigger:value(raw,'trigger_type','trigger')||'Manual',duration:Number(value(raw,'duration_seconds','duration')||0),elapsed:Number(value(raw,'elapsed_seconds','elapsed')||0),cache:Number(value(raw,'cache_hit_percent','cache')||0),time:'Live',logs:[],ticks:0,execution:raw,stepStates:{},real:true};}
  function addRepo(r){if(typeof REPOS!=='undefined'&&!REPOS.some(x=>x.id===r.id))REPOS.unshift(r);if(typeof S!=='undefined'&&!S.projects.some(x=>x.id===r.id))S.projects.unshift(r)}
  function addProject(p){P.backendProjects.set(p.id,p);if(typeof S!=='undefined'){const i=S.projects.findIndex(x=>String(x.id)===p.id||x.backendProjectId===p.id);if(i>=0)S.projects[i]={...S.projects[i],...p};else S.projects.unshift(p);try{persist()}catch{}}}
  async function loadProjects(){const data=await API.projects();for(const raw of array(data))addProject(normalizeProject(raw));return data}
  async function loadGithubRepos(){const installs=array(await API.githubInstallations());P.installations=installs;const repos=[];for(const i of installs){const iid=value(i,'id','installation_id');if(!iid)continue;for(const raw of array(await API.githubRepositories(iid)))repos.push(normalizeRepo(raw,iid))}P.repositories=repos;repos.forEach(addRepo);return repos}
  async function ensureProject(r){if(r.backendProjectId)return r.backendProjectId;const candidates={name:r.name,repository:r.fullName,repository_full_name:r.fullName,repo_full_name:r.fullName,installation_id:r.installationId,github_installation_id:r.installationId,repository_id:r.backendRepoId,branch:r.branch,default_branch:r.branch};const raw=await API.createProject(candidates);const p=normalizeProject(raw);r.backendProjectId=p.id;r.id=p.id;addProject({...r,...p});return p.id}
  async function realAnalyze(){const r=repo(S.wizardRepo);S.wizard=3;S.analysis=1;S.analysisStatus='running';renderView();try{const pid=await ensureProject(r);const analyzePromise=API.analyze(pid);let n=1;const timer=setInterval(()=>{n=Math.min(9,n+1);S.analysis=n;if(S.page==='new')renderView(true)},350);await analyzePromise;clearInterval(timer);const wf=await API.workflow(pid).catch(()=>null);r.backendWorkflow=wf;r.validated=true;r.status='ready';r.confidence=Number(value(wf,'confidence','score')||95);S.analysis=10;S.analysisStatus='complete';audit('Production repository analysis completed',pid,{real:true});persist();renderView(true);announce('Repository analyzed by Application 2')}catch(e){P.lastError=e;S.analysisStatus='failed';announce(`Analysis failed: ${e.message}`,'error');console.error(e)}}
  async function pollRun(r){if(P.runPollers.has(r.backendRunId))return;const tick=async()=>{try{const [raw,steps,logs,events,arts]=await Promise.all([API.run(r.backendRunId),API.steps(r.backendRunId).catch(()=>[]),API.logs(r.backendRunId).catch(()=>[]),API.events(r.backendRunId).catch(()=>[]),API.artifacts(r.backendRunId).catch(()=>[])]);Object.assign(r,normalizeRun(raw,r.project));r.backendSteps=array(steps);r.backendLogs=array(logs);r.backendEvents=array(events);r.backendArtifacts=array(arts);if(typeof renderLive==='function'&&String(S.runId)===String(r.id))renderLive();if(['success','failed','cancelled','incomplete'].includes(r.status)){clearInterval(P.runPollers.get(r.backendRunId));P.runPollers.delete(r.backendRunId);persist()}}catch(e){P.lastError=e;console.warn('run poll failed',e)}};await tick();P.runPollers.set(r.backendRunId,setInterval(tick,cfg.pollIntervalMs))}
  async function realStartRun(projectId,mode='production'){const p=repo(projectId);try{const pid=await ensureProject(p);const payload={branch:p.branch,commit_sha:p.sha&&p.sha!=='pending'&&p.sha!=='resolve-on-analysis'?p.sha:undefined,trigger_type:'manual'};const raw=await API.createRun(pid,payload);const r=normalizeRun(raw,pid);S.runs.unshift(r);S.runId=r.id;persist();closeModal();nav('run/'+r.id+'/pipeline');await pollRun(r);announce('Production pipeline dispatched')}catch(e){P.lastError=e;announce(`Pipeline start failed: ${e.message}`,'error');console.error(e)}}
  async function installGithub(){try{const x=await API.githubInstallUrl();const url=value(x,'url','install_url','html_url');if(url){location.assign(url);return}API.githubOAuthStart()}catch{API.githubOAuthStart()}}
  function adaptLogEntries(original){return function(r){if(r?.real&&Array.isArray(r.backendLogs)&&r.backendLogs.length){return r.backendLogs.map((x,i)=>typeof x==='string'?{id:i+1,time:'',level:'info',step:'remote',message:x}:{id:value(x,'id')||i+1,time:value(x,'timestamp','time')||'',level:value(x,'level')||'info',step:value(x,'step_key','step','stage')||'remote',message:value(x,'message','line','text')||JSON.stringify(x)})}return original(r)}}
  function adaptSteps(original){return function(r){if(r?.real&&Array.isArray(r.backendSteps)&&r.backendSteps.length)return r.backendSteps.map((x,i)=>({id:value(x,'step_key','key','id')||`step-${i+1}`,name:value(x,'name','step_key','key')||`Step ${i+1}`,status:statusMap(value(x,'status')),command:value(x,'command')||'',runtime:value(x,'runtime')||'',exit_code:value(x,'exit_code')}));return original(r)}}
  if(await probe()){
    try{await loadProjects()}catch(e){console.warn('project preload failed',e)}
    try{await loadGithubRepos()}catch(e){console.warn('github preload skipped',e)}
    const oldLogs=typeof logEntries==='function'?logEntries:null;if(oldLogs)logEntries=adaptLogEntries(oldLogs);
    const oldSteps=typeof stepsFor==='function'?stepsFor:null;if(oldSteps)stepsFor=adaptSteps(oldSteps);
    if(typeof ACTIONS!=='undefined'){
      ACTIONS['google-demo']=()=>API.googleStart();
      ACTIONS['connect-github']=()=>installGithub();
      ACTIONS['start-analysis']=()=>realAnalyze();
      ACTIONS['cancel-run']=async b=>{const r=runById(b.dataset.run||S.runId);if(!r?.real)return;await API.cancel(r.backendRunId);announce('Cancellation requested')};
      ACTIONS['diagnose']=async b=>{const r=runById(b.dataset.run||S.runId);if(!r?.real)return investigate(r);try{r.backendDiagnosis=await API.diagnose(r.backendRunId);audit('Production diagnosis completed',r.backendRunId,{real:true});renderView();announce('Evidence-grounded diagnosis ready')}catch(e){announce(e.message,'error')}};
    }
    if(typeof startAnalysis==='function')startAnalysis=realAnalyze;
    if(typeof startRun==='function')startRun=realStartRun;
    try{S.session=true;save('session',true);audit('Production control plane connected','Application2',{real:true,api:cfg.apiBaseUrl});shell();route()}catch{}
  }else if(cfg.demoFallback){console.warn('AutoForge Application 2 unavailable; interactive demo mode retained.');}
})();
